document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".form-broadcast").forEach(n=>{n.addEventListener("submit",function(t){t.preventDefault(),Swal.fire({title:"Broadcast Email?",text:"Email notifikasi kehadiran akan dikirimkan ke seluruh pengurus OSIS.",icon:"bullhorn",iconColor:"#d97706",showCancelButton:!0,confirmButtonColor:"#d97706",cancelButtonColor:"#64748b",confirmButtonText:"Ya, Kirim!",cancelButtonText:"Batal",background:"#ffffff",customClass:{popup:"rounded-[24px]",confirmButton:"rounded-xl font-bold px-4 py-2",cancelButton:"rounded-xl font-medium px-4 py-2"}}).then(t=>{t.isConfirmed&&n.submit()})})}),document.querySelectorAll(".form-delete").forEach(n=>{n.addEventListener("submit",function(t){t.preventDefault(),Swal.fire({title:"Apakah Anda yakin?",text:"Data event dan rekap absensi yang dihapus tidak dapat dikembalikan!",icon:"warning",iconColor:"#e11d48",showCancelButton:!0,confirmButtonColor:"#e11d48",cancelButtonColor:"#64748b",confirmButtonText:"Ya, Hapus!",cancelButtonText:"Batal",background:"#ffffff",customClass:{popup:"rounded-[24px]",confirmButton:"rounded-xl font-bold px-4 py-2",cancelButton:"rounded-xl font-medium px-4 py-2"}}).then(t=>{t.isConfirmed&&n.submit()})})})});